// The parts of contracts/CanaryRegistry.sol that canary-anchor uses.
// Full ABI: contracts/out/CanaryRegistry.abi.json (generated by `npm run compile` in /contracts).
import { keccak256, parseAbiParameters, toBytes } from 'viem'

/** event ClaimAnchored(bytes32 indexed caseId, bytes32 indexed evidenceHash, bytes32 claimantRef, uint64 at) */
export const CLAIM_ANCHORED_SIGNATURE = 'ClaimAnchored(bytes32,bytes32,bytes32,uint64)'
export const CLAIM_ANCHORED_TOPIC = keccak256(toBytes(CLAIM_ANCHORED_SIGNATURE))
/** The event's non-indexed part (log data). */
export const ClaimAnchoredDataParams = parseAbiParameters('bytes32 claimantRef, uint64 at')

const caseStatus = {
	name: '',
	type: 'tuple',
	components: [
		{ name: 'symbol', type: 'string' },
		{ name: 'token', type: 'address' },
		{ name: 'level', type: 'uint8' },
		{ name: 'promoters', type: 'uint32' },
		{ name: 'trailHash', type: 'bytes32' },
		{ name: 'alertAt', type: 'uint64' },
		{ name: 'liquidityBefore', type: 'uint256' },
		{ name: 'liquidityNow', type: 'uint256' },
		{ name: 'dropBps', type: 'uint16' },
		{ name: 'collapsedAt', type: 'uint64' },
		{ name: 'claimCount', type: 'uint32' },
	],
} as const

const claimKey = [
	{ name: 'caseId', type: 'bytes32' },
	{ name: 'evidenceHash', type: 'bytes32' },
] as const

export const CanaryRegistry = [
	{ type: 'function', name: 'getCase', inputs: [{ name: 'caseId', type: 'bytes32' }], outputs: [caseStatus], stateMutability: 'view' },
	{ type: 'function', name: 'claimAnchoredAt', inputs: claimKey, outputs: [{ name: '', type: 'uint64' }], stateMutability: 'view' },
	{
		type: 'function',
		name: 'getClaimVerification',
		inputs: claimKey,
		outputs: [
			{
				name: '',
				type: 'tuple',
				components: [
					{ name: 'claimantRef', type: 'bytes32' },
					{ name: 'walletRef', type: 'bytes32' },
					{ name: 'purchases', type: 'uint32' },
					{ name: 'firstBuyBlock', type: 'uint64' },
					{ name: 'at', type: 'uint64' },
				],
			},
		],
		stateMutability: 'view',
	},
	{
		// Only in registries deployed with report kind 4. On an older registry this call reverts, and the
		// workflow then runs observe-only (it decides and logs, writes nothing).
		type: 'function',
		name: 'getClaimCustody',
		inputs: claimKey,
		outputs: [
			{
				name: '',
				type: 'tuple',
				components: [
					{ name: 'anchorTx', type: 'bytes32' },
					{ name: 'anchorBlock', type: 'uint64' },
					{ name: 'level', type: 'uint8' },
					{ name: 'trailHash', type: 'bytes32' },
					{ name: 'collapsed', type: 'bool' },
					{ name: 'verifiedPurchases', type: 'uint32' },
					{ name: 'poolLiquidityCents', type: 'uint256' },
					{ name: 'mainnetBlock', type: 'uint64' },
					{ name: 'at', type: 'uint64' },
				],
			},
		],
		stateMutability: 'view',
	},
] as const

// Report envelope expected by CanaryRegistry.onReport: abi.encode(uint8 kind, bytes body)
export const REPORT_CLAIM_CUSTODY = 4
export const ReportEnvelopeParams = parseAbiParameters('uint8 kind, bytes body')
// poolLiquidityCents is US cents (USD * 100); 0 with mainnetBlock 0 means "not checked"
export const ClaimCustodyBodyParams = parseAbiParameters(
	'bytes32 caseId, bytes32 evidenceHash, bytes32 anchorTx, uint64 anchorBlock, uint8 level, bytes32 trailHash, bool collapsed, uint32 verifiedPurchases, uint256 poolLiquidityCents, uint64 mainnetBlock',
)
